/// `icon`, its size and colour set by `class`, such as `size-4`, its
/// strokes in the colour of the words; hidden from a screen reader, which
/// reads the words or the label beside it instead.
pub(super) fn icon(icon: &str, class: &str) -> Markup {
    html! {
        svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none"
            stroke="currentColor" stroke-width="2" stroke-linecap="round"
            stroke-linejoin="round" aria-hidden="true"
            class={ "shrink-0 " (class) } {
            (PreEscaped(icon))
        }
    }
}
